function isMirrorChain(head: ListNode | null): boolean {
  if (!head || !head.next) return true;
  const reverse = (node: ListNode | null): ListNode | null => {
    let prev: ListNode | null = null;
    while (node) { const nxt = node.next; node.next = prev; prev = node; node = nxt; }
    return prev;
  };
  let slow = head, fast = head;
  while (fast.next && fast.next.next) { slow = slow.next!; fast = fast.next.next; }
  const second = reverse(slow.next); // slow is the last node of the first half
  let ok = true;
  for (let p: ListNode | null = head, q = second; q; p = p!.next, q = q.next) {
    if (p!.val !== q.val) { ok = false; break; }
  }
  slow.next = reverse(second); // put the list back
  return ok;
}

