  if (!head || !head.next) return true;
  const reverse = (node) => {
    let prev = null;
    while (node) {
      const nxt = node.next;
      node.next = prev;
      prev = node;
      node = nxt;
    }
    return prev;
  };
  let slow = head, fast = head;
  while (fast.next && fast.next.next) {
    slow = slow.next;
    fast = fast.next.next;
  }
  const second = reverse(slow.next);
  let ok = true;
  for (let p = head, q = second; q; p = p.next, q = q.next) {
    if (p.val !== q.val) {
      ok = false;
      break;
    }
  }
  slow.next = reverse(second);
  return ok;
}
